#!/usr/bin/env python3
"""Install Daily Puzzle Hub Tango / Mini Sudoku solver safely."""
from pathlib import Path
from datetime import datetime
import base64
import py_compile
import re
import shutil
import zlib

ROOT=Path(__file__).resolve().parent
FILES={'scripts/logic_solvers.py': '', 'scripts/solve_logic.py': '', 'tests/test_logic_solvers.py': '', 'examples/logic_board_DEMO.json': ''}
HOOK="    from logic_solvers import enrich_daily as _enrich_logic_daily\n    _enrich_logic_daily(day, obj)\n"

def main():
    if not (ROOT/'scripts'/'update.py').exists():
        raise SystemExit('ERROR: Run this installer at the Daily-Puzzle-Hub repository root, next to scripts/update.py.')
    for name,blob in FILES.items():
        dst=ROOT/name
        wanted=zlib.decompress(base64.b64decode(blob))
        if dst.exists() and dst.read_bytes()!=wanted:
            raise SystemExit(f'ERROR: {name} already exists with different contents. No files changed; inspect it before installing.')
    for name,blob in FILES.items():
        dst=ROOT/name
        dst.parent.mkdir(parents=True,exist_ok=True)
        if not dst.exists():
            dst.write_bytes(zlib.decompress(base64.b64decode(blob)))
            print('Installed',name)
        else:
            print('Already current',name)
    for mod in ('scripts/logic_solvers.py','scripts/solve_logic.py'):
        py_compile.compile(str(ROOT/mod),doraise=True)
    p=ROOT/'scripts'/'update.py'
    old=p.read_text(encoding='utf-8')
    if '_enrich_logic_daily(day, obj)' in old:
        print('Updater hook already installed.')
    else:
        matches=list(re.finditer(r'(?m)^    output\.write_text\(',old))
        if len(matches)==1 and 'def update(' in old and "obj={'date':" in old:
            new=old[:matches[0].start()]+HOOK+old[matches[0].start():]
            # Compile before any update to protect the existing updater
            compile(new,str(p),'exec')
            backup=p.with_name('update.py.before_logic_solvers.bak')
            if not backup.exists():
                shutil.copy2(p,backup)
            p.write_text(new,encoding='utf-8')
            print('Added optional original-board hook to scripts/update.py (backup created).')
        else:
            print('NOTE: Updater not patched. No unverified insertion point was found.')
            print('The standalone solver still works. Do not guess an insertion point.')
    print('\nNext: python -m unittest discover -s tests -p test_logic_solvers.py -v')
    print('Then: python scripts/solve_logic.py examples/logic_board_DEMO.json')

if __name__=='__main__':
    main()
